#include "keypad_manager.h"

String KeypadManager::normalizeMac(String value) {
  value.toLowerCase(); String result;
  for (uint16_t i=0; i<value.length(); ++i) if (isHexadecimalDigit(value[i])) result += value[i];
  return result;
}
String KeypadManager::value(const String& json, const char* key) {
  const String needle=String("\"")+key+"\":"; const int start=json.indexOf(needle); if(start<0)return "";
  int begin=start+needle.length(); while(begin<json.length()&&json[begin]==' ')++begin;
  if(begin<json.length()&&json[begin]=='"'){++begin;const int end=json.indexOf('"',begin);return end<0?"":json.substring(begin,end);}
  int end=json.indexOf(',',begin);const int close=json.indexOf('}',begin);if(end<0||(close>=0&&close<end))end=close;return end<0?json.substring(begin):json.substring(begin,end);
}
void KeypadManager::logKeypad(uint8_t i,const char* event){if(logger_&&config_&&i<config_->keypadCount())logger_->log(event,String("Keypad=")+config_->keypad(i).name+" MAC="+config_->keypad(i).mac);}
void KeypadManager::setFault(uint8_t k,bool fault){if(!core_)return;for(uint8_t i=0;i<8;++i){if(fault!=faulted_[k][i]&&logger_){String name=config_->keypad(k).input_names[i];if(!name.length())name=String("input.")+String(i+1);logger_->log(fault?"SENSOR_FAULT":"SENSOR_RESTORED",String("Sensor=")+name+" Keypad="+config_->keypad(k).name); }faulted_[k][i]=fault;core_->setSensor(logicalSlot(k,i),false,fault);}}
void KeypadManager::begin(ConfigStore& config,AlarmCore& core,EventLogger* logger){config_=&config;core_=&core;logger_=logger;for(uint8_t k=0;k<config_->keypadCount();++k){for(uint8_t i=0;i<8;++i){const uint8_t slot=logicalSlot(k,i);core_->setSensorInUse(slot,config_->keypad(k).authorized);core_->setSensorType(slot,config_->keypad(k).input_types[i]);}if(config_->keypad(k).authorized)setFault(k,true);}}
bool KeypadManager::authorized(const String& mac)const{if(!config_)return false;const int8_t i=config_->findKeypad(normalizeMac(mac));return i>=0&&config_->keypad(i).authorized;}
int8_t KeypadManager::enrollIdentity(const String& mac,const String& ip,const String& name,const String& firmware){if(!config_||!mac.length())return -1;KeypadRecord r;const String normalized=normalizeMac(mac);const int8_t old=config_->findKeypad(normalized);if(old>=0)r=config_->keypad(old);r.authorized=true;r.mac=normalized;r.ip=ip;r.name=name;r.firmware=firmware;const int8_t idx=config_->saveKeypad(r);if(idx>=0&&core_)for(uint8_t i=0;i<8;++i){core_->setSensorInUse(logicalSlot(idx,i),true);core_->setSensorType(logicalSlot(idx,i),r.input_types[i]);}return idx;}
bool KeypadManager::receiveHeartbeat(const String& mac,const String& ip,uint32_t now){if(!authorized(mac))return false;const int8_t i=config_->findKeypad(normalizeMac(mac));if(i<0)return false;KeypadRecord r=config_->keypad(i);r.ip=ip;config_->saveKeypad(r);runtime_[i].last_heartbeat=now;if(!runtime_[i].online){runtime_[i].snapshot_pending=true;runtime_[i].online=false;setFault(i,true);}return true;}
bool KeypadManager::receiveSnapshot(const String& mac,const bool open[8],uint32_t now){if(!authorized(mac))return false;const int8_t k=config_->findKeypad(normalizeMac(mac));if(k<0)return false;const bool wasOnline=runtime_[k].online;for(uint8_t i=0;i<8;++i){core_->setSensor(logicalSlot(k,i),open[i],false);remote_open_[k][i]=open[i];remote_known_[k][i]=true;if(faulted_[k][i]&&logger_){String name=config_->keypad(k).input_names[i];if(!name.length())name=String("input.")+String(i+1);logger_->log("SENSOR_RESTORED",String("Sensor=")+name+" State="+(open[i]?"OPEN":"CLOSED"));}faulted_[k][i]=false;}if(!wasOnline)logKeypad(k,"KEYPAD_ONLINE");runtime_[k].snapshot_pending=false;runtime_[k].online=true;runtime_[k].last_heartbeat=now;reconcileSiren(k);reconcileTime(k);return true;}
bool KeypadManager::receiveUpdate(const String& mac,uint8_t channel,bool open,uint32_t now){if(!authorized(mac)||channel<1||channel>8)return false;const int8_t k=config_->findKeypad(normalizeMac(mac));if(k<0||!runtime_[k].online||runtime_[k].snapshot_pending)return false;if(!remote_known_[k][channel-1]||remote_open_[k][channel-1]!=open){remote_open_[k][channel-1]=open;remote_known_[k][channel-1]=true;if(logger_){String name=config_->keypad(k).input_names[channel-1];if(!name.length())name=String("input.")+String(channel);logger_->log(open?"SENSOR_OPEN":"SENSOR_CLOSED",String("Sensor=")+name+" Keypad="+config_->keypad(k).name+" Channel="+String(channel));}}core_->setSensor(logicalSlot(k,channel-1),open,false);runtime_[k].last_heartbeat=now;return true;}
void KeypadManager::connect(uint8_t i,uint32_t now){if(!config_||i>=config_->keypadCount()||!config_->keypad(i).authorized)return;IPAddress ip;if(!ip.fromString(config_->keypad(i).ip)||!clients_[i].connect(ip,acm_protocol::KEYPAD_PORT)){runtime_[i].next_attempt=now+RECONNECT_BACKOFF_MS;return;}runtime_[i].connected=true;runtime_[i].online=false;runtime_[i].snapshot_pending=true;runtime_[i].last_heartbeat=now;setFault(i,true);parsers_[i].reset();acm_protocol::sendFrame(clients_[i],acm_protocol::IDENTIFY_REQUEST,"{\"acm_id\":\"acm\"}");}
void KeypadManager::sendSiren(uint8_t i,bool active){if(i<ConfigStore::MAX_KEYPADS&&runtime_[i].connected&&clients_[i].connected())acm_protocol::sendFrame(clients_[i],active?acm_protocol::LOCAL_SIREN_ON:acm_protocol::LOCAL_SIREN_OFF,String("{\"keypad_id\":\"")+config_->keypad(i).mac+"\"}" );}
void KeypadManager::reconcileSiren(uint8_t i){sendSiren(i,alarm_state_==AlarmState::TRIGGERED);}
void KeypadManager::reconcileTime(uint8_t i){if(i<ConfigStore::MAX_KEYPADS&&time_valid_&&runtime_[i].connected&&clients_[i].connected()){String payload=String("{\"unix\":")+String(time_unix_)+",\"tz\":\"America/Detroit\"}";acm_protocol::sendFrame(clients_[i],acm_protocol::TIME_SYNC,payload);}}
void KeypadManager::setTimeSync(bool valid,uint32_t unix_seconds){time_valid_=valid;time_unix_=unix_seconds;if(valid)for(uint8_t i=0;i<ConfigStore::MAX_KEYPADS;++i)reconcileTime(i);}
bool KeypadManager::takeActionAudit(String& event, String& metadata){if(!pending_audit_event_.length())return false;event=pending_audit_event_;metadata=pending_audit_metadata_;pending_audit_event_="";pending_audit_metadata_="";return true;}
void KeypadManager::handleAction(uint8_t i,const String& frame){
  const String keypadId=value(frame,"keypad_id"); const String action=value(frame,"action"); const String pin=value(frame,"pin");
  bool valid=runtime_[i].online&&keypadId.length()&&normalizeMac(keypadId)==normalizeMac(config_->keypad(i).mac)&&pin.length()>=4&&pin.length()<=12;
  for(uint16_t n=0;valid&&n<pin.length();++n)if(pin[n]<'0'||pin[n]>'9')valid=false;
  RequestType request=RequestType::PIN_AUTH;
  if(action=="ARM_HOME")request=RequestType::ARM_HOME; else if(action=="ARM_AWAY")request=RequestType::ARM_AWAY; else if(action=="DISARM")request=RequestType::DISARM; else valid=false;
  AlarmCore::ActionResult result; if(valid&&core_)result=core_->requestWithPin(request,pin);
  if(valid&&!result.success) { if(logger_) logger_->log("PIN_FAILED",String("Keypad=")+config_->keypad(i).name); }
  if(valid&&result.success){pending_audit_event_=result.current==AlarmState::ARMING_DELAY?"ARMING_DELAY":(result.current==AlarmState::ARMED_HOME?"ARMED_HOME":"DISARMED");pending_audit_metadata_=String("Keypad=")+config_->keypad(i).name+" PIN="+result.auth.friendly_name;}
  if(runtime_[i].connected&&clients_[i].connected()) acm_protocol::sendFrame(clients_[i],acm_protocol::ACTION_RESULT,String("{\"action\":\"")+action+"\",\"success\":"+(valid&&result.success?"true":"false")+"}");
}
void KeypadManager::processFrame(uint8_t i,const String& frame,uint32_t now){const String expected=config_->keypad(i).mac;if(frame.indexOf("\"type\":\"IDENTIFY_RESPONSE\"")>=0){if(normalizeMac(value(frame,"mac"))!=expected){clients_[i].stop();runtime_[i].connected=false;runtime_[i].next_attempt=now+RECONNECT_BACKOFF_MS;return;}acm_protocol::sendFrame(clients_[i],acm_protocol::HELLO_ACM,"{\"acm_id\":\"acm\"}");acm_protocol::sendFrame(clients_[i],acm_protocol::SENSOR_SNAPSHOT_REQUEST,"{\"reason\":\"connect\"}");}else if(frame.indexOf("\"type\":\"HELLO_KEYPAD\"")>=0||frame.indexOf("\"type\":\"HEARTBEAT\"")>=0){const String identity=value(frame,"mac").length()?value(frame,"mac"):value(frame,"keypad_id");if(identity.length()&&normalizeMac(identity)!=expected)return;receiveHeartbeat(expected,value(frame,"ip").length()?value(frame,"ip"):config_->keypad(i).ip,now);}else if(frame.indexOf("\"type\":\"SENSOR_SNAPSHOT\"")>=0){bool states[8]={};const int start=frame.indexOf("\"states\":[");if(start>=0){int p=start+10;for(uint8_t n=0;n<8;++n){const int t=frame.indexOf("true",p),f=frame.indexOf("false",p);if(t<0&&f<0)break;states[n]=t>=0&&(f<0||t<f);p=(states[n]?t:f)+4;}receiveSnapshot(expected,states,now);}}else if(frame.indexOf("\"type\":\"SENSOR_UPDATE\"")>=0){receiveUpdate(expected,static_cast<uint8_t>(value(frame,"channel").toInt()),value(frame,"state")=="OPEN",now);}else if(frame.indexOf("\"type\":\"KEYPAD_ACTION\"")>=0){handleAction(i,frame);}else if(frame.indexOf("\"type\":\"KEYPAD_EVENT\"")>=0&&value(frame,"event")=="PANIC"){logKeypad(i,"PANIC");if(core_)core_->request(RequestType::PANIC);}}
void KeypadManager::process(uint8_t i,uint32_t now){EthernetClient& c=clients_[i];while(c.available()){parsers_[i].feed(static_cast<uint8_t>(c.read()));if(parsers_[i].invalid()){c.stop();runtime_[i].connected=false;return;}if(parsers_[i].complete())processFrame(i,parsers_[i].take(),now);}if(!c.connected()){c.stop();runtime_[i].connected=false;if(runtime_[i].online)logKeypad(i,"KEYPAD_OFFLINE");runtime_[i].online=false;runtime_[i].snapshot_pending=true;setFault(i,true);runtime_[i].next_attempt=now+RECONNECT_BACKOFF_MS;}}
void KeypadManager::broadcastAlarmState(const AlarmSnapshot& snapshot){const bool changed=alarm_state_!=snapshot.state;alarm_state_=snapshot.state;for(uint8_t i=0;i<ConfigStore::MAX_KEYPADS;++i)if(runtime_[i].connected&&clients_[i].connected()){String payload=String("{\"state\":\"")+acm_protocol::alarmStateName(snapshot.state)+"\",\"countdown\":"+String(snapshot.countdown_seconds)+"}";acm_protocol::sendFrame(clients_[i],acm_protocol::ALARM_STATE,payload);if(changed)sendSiren(i,snapshot.state==AlarmState::TRIGGERED);}}
void KeypadManager::tick(uint32_t now){if(!config_||!core_)return;for(uint8_t k=0;k<config_->keypadCount();++k){if(!config_->keypad(k).authorized)continue;if(!runtime_[k].connected&&static_cast<int32_t>(now-runtime_[k].next_attempt)>=0)connect(k,now);if(runtime_[k].connected)process(k,now);if(runtime_[k].online&&static_cast<uint32_t>(now-runtime_[k].last_heartbeat)>=OFFLINE_AFTER_MS){if(runtime_[k].online)logKeypad(k,"KEYPAD_OFFLINE");runtime_[k].online=false;runtime_[k].snapshot_pending=true;setFault(k,true);}}}
bool KeypadManager::enrollKeypad(const IPAddress& ip,uint16_t port){EthernetClient c;if(!c.connect(ip,port))return false;acm_protocol::sendFrame(c,acm_protocol::IDENTIFY_REQUEST,"{\"acm_id\":\"acm\"}");acm_protocol::FrameParser p;const uint32_t deadline=millis()+2000;while(static_cast<int32_t>(millis()-deadline)<0){while(c.available()){p.feed(static_cast<uint8_t>(c.read()));if(p.invalid()){c.stop();return false;}if(p.complete()){const String f=p.take();if(f.indexOf("\"type\":\"IDENTIFY_RESPONSE\"")>=0){const int8_t result=enrollIdentity(value(f,"mac"),ip.toString(),value(f,"name"),value(f,"firmware"));c.stop();return result>=0;}}}delay(1);}c.stop();return false;}
bool KeypadManager::removeKeypad(uint8_t index){if(!config_||index>=config_->keypadCount())return false;if(runtime_[index].connected)clients_[index].stop();runtime_[index]=Runtime{};for(uint8_t i=0;i<8;++i){faulted_[index][i]=false;remote_known_[index][i]=false;core_->setSensorInUse(logicalSlot(index,i),false);}return config_->removeKeypad(index);}
